-- SQL SAFETY: bodies are dollar-quoted; titles and excerpts contain no apostrophes (checked by builder).

-- psssb-junior-engineer-262-posts-20261116 (English 569 words; Nepali 339 words)
INSERT INTO "Article" ("id", "slug", "category", "country", "titleEn", "titleNe", "excerptEn", "excerptNe", "bodyEn", "bodyNe", "sources", "publishedAt", "createdAt", "updatedAt")
VALUES
(gen_random_uuid(), 'psssb-junior-engineer-262-posts-20261116', 'asia', 'India',
'PSSSB Junior Engineer Recruitment 2026: 262 Posts, Apply by 17 November',
'PSSSB जुनियर इन्जिनियर भर्ती २०२६: २६२ पद, १७ नोभेम्बरसम्म आवेदन',
'Punjab Subordinate Services Selection Board has reopened applications for 262 Junior Engineer posts. Civil, Mechanical and Electrical diploma holders can apply at sssb.punjab.gov.in by 17 November 2026.',
'पञ्जाब अधीनस्थ सेवा चयन बोर्डले २६२ जुनियर इन्जिनियर पदका लागि आवेदन फेरि खुलाएको छ। सिभिल, मेकानिकल र इलेक्ट्रिकल डिप्लोमा भएकाले sssb.punjab.gov.in बाट १७ नोभेम्बर २०२६ सम्म आवेदन दिन सक्छन्।',
$$<p>The Punjab Subordinate Services Selection Board (PSSSB) has reopened applications for <strong>262 Junior Engineer posts</strong> under Advertisement 07/2026. The revised notice, dated 11 November 2026, gives candidates a short second window — applications are open from 11 to <strong>17 November 2026</strong>, and the fee must also be paid by 17 November.</p><p>The written examination is scheduled for <strong>6 and 12 December 2026</strong>. Applications are accepted online only at <a href="https://sssb.punjab.gov.in">sssb.punjab.gov.in</a>.</p><h2>At a glance</h2><table><tr><th>Detail</th><th>Information</th></tr><tr><td>Posts</td><td>262 Junior Engineer</td></tr><tr><td>Advertisement</td><td>Advt 07/2026, revised notice 11 November 2026</td></tr><tr><td>Apply online</td><td>11 to 17 November 2026</td></tr><tr><td>Written exam</td><td>6 and 12 December 2026</td></tr><tr><td>Official website</td><td>sssb.punjab.gov.in</td></tr></table><h2>What it offers</h2><p>The 262 posts are split across three disciplines: <strong>Civil 228, Mechanical 2 and Electrical 32</strong>. The vacancies are in Punjab government departments, including Water Resources, PWD (Buildings and Roads), and Rural Development and Panchayats.</p><p>According to secondary sources reporting the original advertisement, the post carries Pay Level 6 (Rs 35,400). The 11 November corrigendum itself does not restate the pay scale, so candidates should confirm it from the detailed advertisement on the board website.</p><h2>Who can apply</h2><p>The corrigendum does not restate the eligibility conditions. Secondary sources reporting the original advertisement say applicants need a three-year diploma (or degree) in the relevant discipline — Civil, Mechanical or Electrical — and must have passed Punjabi at Matric level. The reported age limit is 18 to 37 years as on 1 January 2026.</p><p>Because these details come from secondary reporting of the original advertisement rather than the revised notice, candidates should read the detailed advertisement on sssb.punjab.gov.in before applying.</p><h2>How to apply</h2><ol><li>Go to sssb.punjab.gov.in and open Advertisement 07/2026.</li><li>Fill in the online form and upload the required documents.</li><li>Pay the fee and submit the form by 17 November 2026.</li></ol><p>The application window closes on 17 November, so there is no time to wait. Submit the form and keep a copy of the acknowledgement for the December examination.</p><h2>What the notification does not say</h2><p>The revised notice of 11 November 2026 does not state the application fee, the age limit, or the pay scale. A fee chart of Rs 1,700 (General), Rs 950 (SC-BC) and Rs 700 (EWS-ESM-PH) is circulating on social media, but it comes from a single unverified poster and is not reproduced in the corrigendum — do not treat it as the official fee. Check the detailed advertisement on the board website for the fee, eligibility and pay before paying anything.</p><p>Never pay anyone who offers to get you selected. PSSSB does not charge for selection, and no agent or middleman can influence the result.</p><h2>Sources</h2><p>Revised notice summary: Testbook PSSSB JE article; Karmasandhan PSSSB JE notice. Official website: <a href="https://sssb.punjab.gov.in">sssb.punjab.gov.in</a>.</p>$$,
$$<p>पञ्जाब अधीनस्थ सेवा चयन बोर्ड (PSSSB) ले विज्ञापन ०७/२०२६ अन्तर्गत <strong>२६२ जुनियर इन्जिनियर पद</strong> का लागि आवेदन फेरि खुलाएको छ। ११ नोभेम्बर २०२६ को संशोधित सूचनाले छोटो दोस्रो अवसर दिएको छ — आवेदन <strong>११ देखि १७ नोभेम्बर २०२६</strong> सम्म खुला छ र शुल्क पनि १७ नोभेम्बरसम्म बुझाउनुपर्छ।</p><p>लिखित परीक्षा <strong>६ र १२ डिसेम्बर २०२६</strong> मा हुनेछ। आवेदन अनलाइन मात्र <a href="https://sssb.punjab.gov.in">sssb.punjab.gov.in</a> बाट दिन सकिन्छ।</p><h2>एक नजरमा</h2><table><tr><th>विवरण</th><th>जानकारी</th></tr><tr><td>पद</td><td>२६२ जुनियर इन्जिनियर</td></tr><tr><td>विज्ञापन</td><td>विज्ञापन ०७/२०२६, संशोधित सूचना ११ नोभेम्बर २०२६</td></tr><tr><td>आवेदन</td><td>११ देखि १७ नोभेम्बर २०२६</td></tr><tr><td>लिखित परीक्षा</td><td>६ र १२ डिसेम्बर २०२६</td></tr><tr><td>आधिकारिक वेबसाइट</td><td>sssb.punjab.gov.in</td></tr></table><h2>के छ</h2><p>२६२ पद तीन विषयमा बाँडिएका छन्: <strong>सिभिल २२८, मेकानिकल २ र इलेक्ट्रिकल ३२</strong>। पदहरू जलस्रोत, PWD (भवन तथा सडक) र ग्रामीण विकास तथा पञ्चायतसहितका पञ्जाब सरकारका विभागहरूमा छन्।</p><p>मूल विज्ञापनबारे लेख्ने स्रोतहरूका अनुसार यो पदको तलबस्तर लेभल ६ (रु ३५,४००) हो। तर ११ नोभेम्बरको संशोधित सूचनामा तलबस्तर उल्लेख छैन, त्यसैले बोर्डको वेबसाइटमा विस्तृत विज्ञापन हेरेर यकिन गर्नुहोस्।</p><h2>कसले आवेदन दिन सक्छ</h2><p>संशोधित सूचनामा योग्यताका सर्तहरू दोहोर्‍याइएको छैन। मूल विज्ञापनबारे लेख्ने स्रोतहरूका अनुसार सम्बन्धित विषयमा तीन वर्षे डिप्लोमा (वा डिग्री) र म्याट्रिक तहमा पञ्जाबी पास गरेको हुनुपर्छ। उमेर सीमा १ जनवरी २०२६ का दिन १८ देखि ३७ वर्ष भनिएको छ।</p><p>यी विवरणहरू संशोधित सूचनाबाट होइन, मूल विज्ञापनबारेको माध्यमिक रिपोर्टबाट आएका हुन्, त्यसैले आवेदन दिनुभन्दा अघि sssb.punjab.gov.in मा विस्तृत विज्ञापन पढ्नुहोस्।</p><h2>कसरी आवेदन दिने</h2><ol><li>sssb.punjab.gov.in मा गएर विज्ञापन ०७/२०२६ खोल्नुहोस्।</li><li>अनलाइन फारम भर्नुहोस् र आवश्यक कागजात अपलोड गर्नुहोस्।</li><li>शुल्क बुझाएर १७ नोभेम्बर २०२६ सम्म फारम बुझाउनुहोस्।</li></ol><p>आवेदनको म्याद १७ नोभेम्बरमा सकिन्छ, त्यसैले ढिला नगर्नुहोस्। फारम बुझाएपछि स्वीकृतिको प्रतिलिपि राख्नुहोस्।</p><h2>सूचनामा के छैन</h2><p>११ नोभेम्बर २०२६ को संशोधित सूचनामा आवेदन शुल्क, उमेर सीमा वा तलबस्तर उल्लेख छैन। सामाजिक सञ्जालमा रु १,७०० (सामान्य), रु ९५० (SC-BC) र रु ७०० (EWS-ESM-PH) को शुल्क तालिका घुमिरहेको छ, तर त्यो एउटा अपुष्ट पोस्टरबाट आएको हो र संशोधित सूचनामा छैन — त्यसलाई आधिकारिक शुल्क नठान्नुहोस्। शुल्क, योग्यता र तलबका लागि बोर्डको वेबसाइटमा विस्तृत विज्ञापन हेर्नुहोस्।</p><p>छनोट गराइदिने भन्दै कसैलाई पनि पैसा नदिनुहोस्। PSSSB ले छनोटका लागि शुल्क लिँदैन र कुनै दलालले नतिजामा असर पार्न सक्दैन।</p><h2>स्रोतहरू</h2><p>संशोधित सूचना सारांश: Testbook PSSSB JE लेख; Karmasandhan PSSSB JE सूचना। आधिकारिक वेबसाइट: <a href="https://sssb.punjab.gov.in">sssb.punjab.gov.in</a>।</p>$$,
ARRAY['https://sssb.punjab.gov.in', 'https://testbook.com/psssb-je-recruitment', 'https://www.karmasandhan.com/psssb-je-recruitment-2026'], NOW(), NOW(), NOW()) ON CONFLICT ("slug") DO NOTHING;

-- lok-sewa-section-officer-509-posts-20261116 (English 660 words; Nepali 427 words)
INSERT INTO "Article" ("id", "slug", "category", "country", "titleEn", "titleNe", "excerptEn", "excerptNe", "bodyEn", "bodyNe", "sources", "publishedAt", "createdAt", "updatedAt")
VALUES
(gen_random_uuid(), 'lok-sewa-section-officer-509-posts-20261116', 'nepal', 'Nepal',
'Lok Sewa Section Officer Vacancy 2083: 509 Posts, Apply by 1 December',
'लोक सेवा शाखा अधिकृत विज्ञापन २०८३: ५०९ पद, १ डिसेम्बरसम्म आवेदन',
'Lok Sewa Aayog has opened 509 Section Officer posts across civil, parliamentary, human rights and health services. Applications close on 1 December 2026 at psconline.psc.gov.np.',
'लोक सेवा आयोगले निजामती, संसद्, मानव अधिकार र स्वास्थ्य सेवामा ५०९ शाखा अधिकृत पद खुलाएको छ। आवेदन १ डिसेम्बर २०२६ सम्म psconline.psc.gov.np बाट दिन सकिन्छ।',
$$<p>The Public Service Commission (Lok Sewa Aayog) has opened <strong>509 Section Officer posts</strong> in the open competitive examination for Gazetted Third Class positions. The notice covers the Civil Service, the Federal Parliament Service, the National Human Rights Service and the Nepal Health Service, with the biggest groups in Computer and IT, Civil Engineering, Law and Health.</p><p>Applications are accepted online only at <a href="https://psconline.psc.gov.np">psconline.psc.gov.np</a>. The last date with the normal fee is <strong>1 December 2026</strong> (Mangsir 15, 2083), and applications are accepted with double fee until <strong>8 December 2026</strong> (Mangsir 22, 2083).</p><h2>At a glance</h2><table><tr><th>Detail</th><th>Information</th></tr><tr><td>Posts</td><td>509 competitive (691 total including 182 promotion posts)</td></tr><tr><td>Notice</td><td>759/083-84</td></tr><tr><td>Apply online</td><td>psconline.psc.gov.np</td></tr><tr><td>Last date (normal fee)</td><td>1 December 2026</td></tr><tr><td>Last date (double fee)</td><td>8 December 2026</td></tr><tr><td>Fee</td><td>NPR 1,200 per advertisement</td></tr></table><h2>What it offers</h2><p>The 509 competitive posts are spread across many services and groups. The largest groups in the vacancy infographic published by the Commission are <strong>Computer and Information Technology 107, Civil Engineering 103, Justice, Law and Government Attorney 96, and Health and Medical 91</strong>. The remaining posts are in administration, revenue, audit, foreign affairs, education and other groups.</p><p>Section Officer is a Gazetted Third Class post — the entry point to Nepal officer-level civil service. Selection is by written examination followed by interview.</p><h2>Who can apply</h2><p>Applicants need a bachelor degree or equivalent qualification as required for the service and group they apply for. The age limit is <strong>21 to 35 years</strong>, rising to 40 for women and disabled candidates; for health service posts the age range is 18 to 45 years.</p><p>Candidates must check the service-wise and group-wise qualification requirements in the notice before applying, because the required degree differs by group — for example, engineering groups need an engineering degree and health groups need a health qualification.</p><h2>How to apply</h2><ol><li>Go to psconline.psc.gov.np and register or log in.</li><li>Choose the Section Officer advertisement (Notice 759/083-84) and the service and group you are eligible for.</li><li>Fill in the form, upload the required documents and pay NPR 1,200 per advertisement.</li><li>Submit by 1 December 2026 with the normal fee, or by 8 December 2026 with double fee.</li></ol><p>Keep the payment receipt and the submitted application safe — you will need them for the written examination.</p><h2>What the notification does not say</h2><p>The examination date is not stated in the vacancy notice, so do not trust any date circulating on social media for this examination. One carousel post carried a date that has already passed — it does not apply to this notice.</p><p>The post count of 509 competitive posts is as published in the vacancy infographic issued by the Commission. The notice number is also reported differently in different sources — 759/083-84 in one reproduction and 789/082-84 in another — so confirm the number from the notice on psc.gov.np when you apply.</p><p>Never pay anyone who promises to get you selected in Lok Sewa. The Commission does not charge for selection, and no agent can influence the result.</p><h2>Sources</h2><p>Public Service Commission notices: <a href="https://psc.gov.np">psc.gov.np</a>. Online application: <a href="https://psconline.psc.gov.np">psconline.psc.gov.np</a>. Notice reproduction: EducateNepal blog; Collegenp Lok Sewa vacancy listing.</p>$$,
$$<p>लोक सेवा आयोगले राजपत्राङ्कित तृतीय श्रेणीका पदहरूमा खुला प्रतियोगितात्मक परीक्षाबाट <strong>५०९ शाखा अधिकृत पद</strong> खुलाएको छ। यो सूचनामा निजामती सेवा, संघीय संसद् सेवा, राष्ट्रिय मानव अधिकार सेवा र नेपाल स्वास्थ्य सेवा समेटिएका छन्, जसमा कम्प्युटर तथा सूचना प्रविधि, सिभिल इन्जिनियरिङ, कानुन र स्वास्थ्य समूहमा सबैभन्दा धेरै पद छन्।</p><p>आवेदन अनलाइन मात्र <a href="https://psconline.psc.gov.np">psconline.psc.gov.np</a> बाट दिन सकिन्छ। सामान्य शुल्कमा आवेदन दिने अन्तिम मिति <strong>१ डिसेम्बर २०२६</strong> (मंसिर १५, २०८३) हो र दोब्बर शुल्कमा <strong>८ डिसेम्बर २०२६</strong> (मंसिर २२, २०८३) सम्म आवेदन दिन सकिन्छ।</p><h2>एक नजरमा</h2><table><tr><th>विवरण</th><th>जानकारी</th></tr><tr><td>पद</td><td>५०९ प्रतियोगितात्मक (बढुवा १८२ सहित जम्मा ६९१)</td></tr><tr><td>सूचना</td><td>७५९/०८३-८४</td></tr><tr><td>अनलाइन आवेदन</td><td>psconline.psc.gov.np</td></tr><tr><td>अन्तिम मिति (सामान्य शुल्क)</td><td>१ डिसेम्बर २०२६</td></tr><tr><td>अन्तिम मिति (दोब्बर शुल्क)</td><td>८ डिसेम्बर २०२६</td></tr><tr><td>शुल्क</td><td>प्रति विज्ञापन रु १,२००</td></tr></table><h2>के छ</h2><p>५०९ प्रतियोगितात्मक पद विभिन्न सेवा र समूहमा बाँडिएका छन्। आयोगले प्रकाशन गरेको रिक्त पदको इन्फोग्राफिक अनुसार सबैभन्दा धेरै पदहरू <strong>कम्प्युटर तथा सूचना प्रविधि १०७, सिभिल इन्जिनियरिङ १०३, न्याय, कानुन तथा सरकारी वकिल ९६, र स्वास्थ्य तथा चिकित्सा ९१</strong> छन्। बाँकी पदहरू प्रशासन, राजस्व, लेखापरीक्षण, परराष्ट्र, शिक्षा र अन्य समूहमा छन्।</p><p>शाखा अधिकृत राजपत्राङ्कित तृतीय श्रेणीको पद हो — नेपालको अधिकृतस्तर निजामती सेवामा प्रवेश गर्ने बाटो। छनोट लिखित परीक्षा र अन्तर्वार्ताबाट हुन्छ।</p><h2>कसले आवेदन दिन सक्छ</h2><p>आवेदन गर्ने सेवा र समूहअनुसार स्नातक तह वा सो सरहको योग्यता चाहिन्छ। उमेर सीमा <strong>२१ देखि ३५ वर्ष</strong> हो; महिला तथा अपाङ्गता भएका उम्मेदवारका लागि ४० वर्षसम्म र स्वास्थ्य सेवा पदका लागि १८ देखि ४५ वर्ष छ।</p><p>आवेदन गर्नुअघि सूचनामा सेवा र समूहअनुसारको योग्यता हेर्नुहोस्, किनभने आवश्यक डिग्री समूहअनुसार फरक हुन्छ — जस्तै इन्जिनियरिङ समूहमा इन्जिनियरिङ डिग्री र स्वास्थ्य समूहमा स्वास्थ्यसम्बन्धी योग्यता चाहिन्छ।</p><h2>कसरी आवेदन दिने</h2><ol><li>psconline.psc.gov.np मा गएर दर्ता गर्नुहोस् वा लगइन गर्नुहोस्।</li><li>शाखा अधिकृत विज्ञापन (सूचना ७५९/०८३-८४) र आफू योग्य भएको सेवा र समूह छान्नुहोस्।</li><li>फारम भर्नुहोस्, आवश्यक कागजात अपलोड गर्नुहोस् र प्रति विज्ञापन रु १,२०० शुल्क तिर्नुहोस्।</li><li>सामान्य शुल्कमा १ डिसेम्बर २०२६ सम्म वा दोब्बर शुल्कमा ८ डिसेम्बर २०२६ सम्म बुझाउनुहोस्।</li></ol><p>भुक्तानीको रसिद र बुझाएको आवेदन सुरक्षित राख्नुहोस् — लिखित परीक्षामा तिनको आवश्यकता पर्छ।</p><h2>सूचनामा के छैन</h2><p>परीक्षाको मिति रिक्त पदको सूचनामा उल्लेख छैन, त्यसैले सामाजिक सञ्जालमा घुमिरहेको कुनै पनि मितिलाई यो परीक्षाको मिति नठान्नुहोस्। एउटा पोस्टमा बितिसकेको मिति थियो — त्यो यो सूचनामा लागू हुँदैन।</p><p>५०९ प्रतियोगितात्मक पदको संख्या आयोगले प्रकाशन गरेको रिक्त पदको इन्फोग्राफिकअनुसार हो। सूचना नम्बर पनि स्रोतअनुसार फरक छ — एउटामा ७५९/०८३-८४ र अर्कोमा ७८९/०८२-८४ लेखिएको छ — त्यसैले आवेदन गर्दा psc.gov.np मा सूचना हेरेर नम्बर यकिन गर्नुहोस्।</p><p>लोक सेवामा छनोट गराइदिने भन्दै कसैलाई पनि पैसा नदिनुहोस्। आयोगले छनोटका लागि शुल्क लिँदैन र कुनै दलालले नतिजामा असर पार्न सक्दैन।</p><h2>स्रोतहरू</h2><p>लोक सेवा आयोगका सूचनाहरू: <a href="https://psc.gov.np">psc.gov.np</a>। अनलाइन आवेदन: <a href="https://psconline.psc.gov.np">psconline.psc.gov.np</a>। सूचना प्रतिलिपि: EducateNepal ब्लग; Collegenp लोक सेवा रिक्त पद सूची।</p>$$,
ARRAY['https://psc.gov.np', 'https://psconline.psc.gov.np', 'https://www.collegenp.com/tag/lok-sewa-aayog-vacancy'], NOW(), NOW(), NOW()) ON CONFLICT ("slug") DO NOTHING;

-- usda-aphis-hiring-event-228-jobs-edinburg-texas-20261116 (English 544 words; Nepali 355 words)
INSERT INTO "Article" ("id", "slug", "category", "country", "titleEn", "titleNe", "excerptEn", "excerptNe", "bodyEn", "bodyNe", "sources", "publishedAt", "createdAt", "updatedAt")
VALUES
(gen_random_uuid(), 'usda-aphis-hiring-event-228-jobs-edinburg-texas-20261116', 'usa', 'USA',
'USDA APHIS Hiring Event 2026: 228 Jobs in Edinburg, Texas, Apply on USAJOBS',
'USDA APHIS भर्ती कार्यक्रम २०२६: टेक्सासमा २२८ जागिर, USAJOBS बाट आवेदन',
'The US Department of Agriculture is hiring 228 people at a three-day event in Edinburg, Texas, from 17 to 19 November 2026. Applications are open now on USAJOBS.',
'अमेरिकी कृषि विभागले टेक्सासको एडिनबर्गमा १७ देखि १९ नोभेम्बर २०२६ सम्म तीन दिने कार्यक्रममा २२८ जना नियुक्त गर्दैछ। आवेदन अहिले USAJOBS मा खुला छ।',
$$<p>The United States Department of Agriculture (USDA) is hiring <strong>228 people</strong> at a three-day hiring event in Edinburg, Texas, from Monday 17 to Wednesday 19 November 2026. The event covers the Animal and Plant Health Inspection Service (APHIS) — its Plant Protection and Quarantine and Veterinary Services programmes — and some candidates can be selected on the spot.</p><p>Job postings have been open on USAJOBS since 10 November 2026. The hiring event runs from <strong>10 AM to 5 PM Central Time</strong> at Palmer Plantation, 41601 La Peninsula Drive, Edinburg, Texas.</p><h2>At a glance</h2><table><tr><th>Detail</th><th>Information</th></tr><tr><td>Posts</td><td>228 selectees anticipated</td></tr><tr><td>Employer</td><td>USDA APHIS — Plant Protection and Quarantine / Veterinary Services</td></tr><tr><td>Hiring event</td><td>17–19 November 2026, 10 AM–5 PM CT</td></tr><tr><td>Venue</td><td>Palmer Plantation, 41601 La Peninsula Dr, Edinburg, TX</td></tr><tr><td>Apply online</td><td>USAJOBS (usajobs.gov)</td></tr><tr><td>Fee</td><td>None</td></tr></table><h2>What it offers</h2><p>USDA expects to make 228 selections through this hiring event. APHIS protects American agriculture and livestock — its Plant Protection and Quarantine staff keep plant pests and diseases out of the country, and its Veterinary Services staff protect animal health.</p><p>Candidates who attend the event can meet hiring managers in person, and the department has said some applicants will be selected on the spot. Federal hiring carries no application fee, and there is no charge to attend the event.</p><h2>Who can apply</h2><p>Veterans and disabled applicants receive non-competitive appointment preference under federal hiring rules. Applicants need a valid driver licence and a REAL ID to attend, and successful candidates must pass a criminal background check, a drug test and fingerprinting.</p><p>Because the postings cover a range of APHIS roles, candidates should search USDA APHIS on USAJOBS and read each announcement for its own grade, duties and qualifications before applying.</p><h2>How to apply</h2><ol><li>Go to usajobs.gov and search for USDA APHIS.</li><li>Read the announcement for the role you want and apply online.</li><li>Attend the Edinburg hiring event on 17, 18 or 19 November between 10 AM and 5 PM CT, with your REAL ID and the documents the announcement asks for.</li></ol><p>The event lasts only three days, so apply on USAJOBS now and plan to attend early in the week.</p><h2>What the announcement does not say</h2><p>The sources do not list the specific job titles or grades open at the event, the exact closing date of each USAJOBS announcement, or the pay for the roles. Do not rely on any salary figure circulating online for this event — check the individual announcement on USAJOBS.</p><p>Never pay anyone who offers to get you a federal job. US federal hiring is free, and no agent can influence a selection.</p><h2>Sources</h2><p>USAJOBS: <a href="https://www.usajobs.gov">usajobs.gov</a>. Event reporting: KRGV / ValleyCentral; Hidalgo County official event page and press release.</p>$$,
$$<p>अमेरिकी कृषि विभाग (USDA) ले टेक्सासको एडिनबर्गमा सोमबार १७ देखि बुधबार १९ नोभेम्बर २०२६ सम्म तीन दिने भर्ती कार्यक्रममा <strong>२२८ जना</strong> नियुक्त गर्दैछ। यो कार्यक्रम पशु तथा वनस्पति स्वास्थ्य निरीक्षण सेवा (APHIS) — वनस्पति संरक्षण तथा क्वारेन्टाइन र पशु चिकित्सा सेवा कार्यक्रमहरू — का लागि हो, र केही उम्मेदवारलाई कार्यक्रममै छनोट गरिनेछ।</p><p>USAJOBS मा जागिरका विज्ञापनहरू १० नोभेम्बर २०२६ देखि खुला छन्। भर्ती कार्यक्रम <strong>बिहान १० बजेदेखि साँझ ५ बजेसम्म सेन्ट्रल समय</strong> मा पामर प्लान्टेसन, ४१६०१ ला पेनिन्सुला ड्राइभ, एडिनबर्ग, टेक्सासमा हुनेछ।</p><h2>एक नजरमा</h2><table><tr><th>विवरण</th><th>जानकारी</th></tr><tr><td>पद</td><td>२२८ छनोट अपेक्षित</td></tr><tr><td>रोजगारदाता</td><td>USDA APHIS — वनस्पति संरक्षण तथा क्वारेन्टाइन / पशु चिकित्सा सेवा</td></tr><tr><td>भर्ती कार्यक्रम</td><td>१७–१९ नोभेम्बर २०२६, बिहान १०–साँझ ५ बजे CT</td></tr><tr><td>स्थल</td><td>पामर प्लान्टेसन, ४१६०१ ला पेनिन्सुला ड्राइभ, एडिनबर्ग, TX</td></tr><tr><td>अनलाइन आवेदन</td><td>USAJOBS (usajobs.gov)</td></tr><tr><td>शुल्क</td><td>छैन</td></tr></table><h2>के छ</h2><p>USDA ले यो भर्ती कार्यक्रमबाट २२८ छनोट गर्ने अपेक्षा गरेको छ। APHIS ले अमेरिकी कृषि र पशुधनको रक्षा गर्छ — वनस्पति संरक्षण तथा क्वारेन्टाइन कर्मचारीहरूले वनस्पति रोग र कीराहरू देशभित्र पस्नबाट रोक्छन् र पशु चिकित्सा सेवा कर्मचारीहरूले पशु स्वास्थ्यको रक्षा गर्छन्।</p><p>कार्यक्रममा उपस्थित उम्मेदवारहरूले नियुक्ति प्रबन्धकहरूलाई प्रत्यक्ष भेट्न सक्छन्, र विभागले केही आवेदकलाई कार्यक्रममै छनोट गर्ने बताएको छ। संघीय भर्तीमा आवेदन शुल्क लाग्दैन र कार्यक्रममा सहभागी हुन पनि कुनै शुल्क छैन।</p><h2>कसले आवेदन दिन सक्छ</h2><p>संघीय भर्ती नियमअनुसार भूतपूर्व सैनिक र अपाङ्गता भएका आवेदकलाई गैर-प्रतिस्पर्धात्मक नियुक्ति प्राथमिकता दिइन्छ। आवेदकसँग वैध चालक अनुमतिपत्र र REAL ID हुनुपर्छ, र छनोट भएकाले आपराधिक पृष्ठभूमि जाँच, लागुऔषध परीक्षण र फिंगरप्रिन्ट पार गर्नुपर्छ।</p><p>विज्ञापनहरूले विभिन्न APHIS पदहरू समेट्ने भएकाले उम्मेदवारले USAJOBS मा USDA APHIS खोजेर प्रत्येक विज्ञापनको श्रेणी, कर्तव्य र योग्यता पढ्नुपर्छ।</p><h2>कसरी आवेदन दिने</h2><ol><li>usajobs.gov मा गएर USDA APHIS खोज्नुहोस्।</li><li>चाहेको पदको विज्ञापन पढेर अनलाइन आवेदन दिनुहोस्।</li><li>१७, १८ वा १९ नोभेम्बरमा बिहान १० बजेदेखि साँझ ५ बजेसम्म (CT) REAL ID र विज्ञापनले मागेका कागजात लिएर एडिनबर्ग भर्ती कार्यक्रममा उपस्थित हुनुहोस्।</li></ol><p>कार्यक्रम तीन दिन मात्र छ, त्यसैले अहिले नै USAJOBS बाट आवेदन दिनुहोस् र हप्ताको सुरुमै उपस्थित हुने योजना बनाउनुहोस्।</p><h2>विज्ञापनमा के छैन</h2><p>स्रोतहरूमा कार्यक्रममा खुला विशिष्ट पद वा श्रेणी, प्रत्येक USAJOBS विज्ञापनको ठ्याक्कै अन्तिम मिति वा तलब उल्लेख छैन। यो कार्यक्रमका लागि अनलाइन घुमिरहेको कुनै पनि तलबको आँकडामा भर नपर्नुहोस् — USAJOBS मा सम्बन्धित विज्ञापन हेर्नुहोस्।</p><p>संघीय जागिर दिलाइदिने भन्दै कसैलाई पनि पैसा नदिनुहोस्। अमेरिकी संघीय भर्ती निःशुल्क छ र कुनै दलालले छनोटमा असर पार्न सक्दैन।</p><h2>स्रोतहरू</h2><p>USAJOBS: <a href="https://www.usajobs.gov">usajobs.gov</a>। कार्यक्रम रिपोर्ट: KRGV / ValleyCentral; हिडाल्गो काउन्टी आधिकारिक कार्यक्रम पृष्ठ र प्रेस विज्ञप्ति।</p>$$,
ARRAY['https://www.usajobs.gov', 'https://www.krgv.com', 'https://www.hidalgocounty.us'], NOW(), NOW(), NOW()) ON CONFLICT ("slug") DO NOTHING;

-- royal-mail-christmas-jobs-22000-temporary-roles-20261116 (English 552 words; Nepali 369 words)
INSERT INTO "Article" ("id", "slug", "category", "country", "titleEn", "titleNe", "excerptEn", "excerptNe", "bodyEn", "bodyNe", "sources", "publishedAt", "createdAt", "updatedAt")
VALUES
(gen_random_uuid(), 'royal-mail-christmas-jobs-22000-temporary-roles-20261116', 'uk', 'UK',
'Royal Mail Christmas Jobs 2026: 22,000 Temporary Roles, No Experience Needed',
'रोयल मेल क्रिसमस जागिर २०२६: २२,००० अस्थायी पद, अनुभव आवश्यक छैन',
'Royal Mail is hiring almost 22,000 temporary staff for Christmas 2026 across the UK. No experience is needed and applications close when caps are reached.',
'रोयल मेलले क्रिसमस २०२६ का लागि बेलायतभर लगभग २२,००० अस्थायी कर्मचारी भर्ती गर्दैछ। अनुभव आवश्यक छैन र आवेदन सीमा पुगेपछि बन्द हुन्छ।',
$$<p>Royal Mail is hiring almost <strong>22,000 temporary staff</strong> for Christmas 2026 across the United Kingdom. The roles cover mail sorting, delivery and driving, and no previous experience is needed — the company says it is recruiting people who want to earn extra money over the festive season.</p><p>Applications opened with the announcement on 29 September 2026 and are being accepted on a rolling basis. There is <strong>no fixed closing date</strong> — vacancies close when application caps are reached, so some roles may already be filled.</p><h2>At a glance</h2><table><tr><th>Detail</th><th>Information</th></tr><tr><td>Posts</td><td>Almost 22,000 temporary roles</td></tr><tr><td>Employer</td><td>Royal Mail</td></tr><tr><td>Apply online</td><td>careers.royalmailgroup.com/christmas</td></tr><tr><td>Deadline</td><td>Rolling — no fixed date, closes when caps are reached</td></tr><tr><td>Work period</td><td>Late October 2026 to early January 2027</td></tr><tr><td>Fee</td><td>None</td></tr></table><h2>What it offers</h2><p>The 22,000 roles are split across the UK: <strong>12,500 mail sorting roles in England, 1,243 in Scotland, 485 in Northern Ireland and 355 in Wales</strong>. There are also <strong>5,000 delivery and collection driving roles</strong> and <strong>2,100 HGV and MGV driving roles</strong>.</p><p>The work runs from late October 2026 into early January 2027, covering the Christmas peak — the busiest time of year for Royal Mail. Most roles are short-term and seasonal, not permanent jobs.</p><h2>Who can apply</h2><p>No previous experience is needed for sorting and most other roles. Applicants must meet Royal Mail recruitment checks. Driving roles need the relevant licence — HGV and MGV driver roles need an HGV or MGV licence.</p><p>Anyone legally allowed to work in the UK can apply. The roles suit people looking for temporary Christmas work, including students, part-time workers and anyone wanting extra income in December.</p><h2>How to apply</h2><ol><li>Go to careers.royalmailgroup.com/christmas.</li><li>Choose your area and the role you want.</li><li>Complete the online application and the recruitment checks.</li></ol><p>Because there is no fixed deadline and roles close when caps are reached, apply as soon as possible — popular locations fill first.</p><h2>What the announcement does not say</h2><p>Royal Mail has not published a fixed closing date, and the announcement does not state the pay rates for the roles. A pay figure of £16.44 an hour for one night-sorter listing has been quoted online, but that comes from a single listing, not the official announcement — do not treat it as the pay for these roles. Check the individual vacancy on the Royal Mail careers site for its own pay and hours.</p><p>Never pay anyone who offers to get you a Royal Mail job. Applications are free on the official careers site, and no agent can influence a selection.</p><h2>Sources</h2><p>Official Christmas hub: <a href="https://careers.royalmailgroup.com/christmas">careers.royalmailgroup.com/christmas</a>. Announcement reporting: The Mirror, 29 September 2026; The Sun; Daily Express.</p>$$,
$$<p>रोयल मेलले क्रिसमस २०२६ का लागि संयुक्त अधिराज्यभर <strong>लगभग २२,००० अस्थायी कर्मचारी</strong> भर्ती गर्दैछ। यी पदहरू हुलाक छानबिन, वितरण र सवारी चालकका हुन् र अघिल्लो अनुभव आवश्यक छैन — कम्पनीले चाडपर्वको समयमा थप आम्दानी गर्न चाहनेहरूलाई भर्ती गरिरहेको बताएको छ।</p><p>आवेदन २९ सेप्टेम्बर २०२६ को घोषणासँगै खुलेको छ र क्रमिक रूपमा स्वीकार गरिँदैछ। <strong>कुनै निश्चित अन्तिम मिति छैन</strong> — आवेदन सीमा पुगेपछि रिक्त पद बन्द हुन्छ, त्यसैले केही पदहरू भरिसकेका पनि हुन सक्छन्।</p><h2>एक नजरमा</h2><table><tr><th>विवरण</th><th>जानकारी</th></tr><tr><td>पद</td><td>लगभग २२,००० अस्थायी पद</td></tr><tr><td>रोजगारदाता</td><td>रोयल मेल</td></tr><tr><td>अनलाइन आवेदन</td><td>careers.royalmailgroup.com/christmas</td></tr><tr><td>अन्तिम मिति</td><td>क्रमिक — निश्चित मिति छैन, सीमा पुगेपछि बन्द हुन्छ</td></tr><tr><td>कामको अवधि</td><td>अक्टोबर २०२६ अन्त्यदेखि जनवरी २०२७ सुरुसम्म</td></tr><tr><td>शुल्क</td><td>छैन</td></tr></table><h2>के छ</h2><p>२२,००० पद बेलायतभर बाँडिएका छन्: <strong>इङ्गल्याण्डमा १२,५०० हुलाक छानबिन पद, स्कटल्यान्डमा १,२४३, उत्तरी आयरल्यान्डमा ४८५ र वेल्समा ३५५</strong>। त्यसबाहेक <strong>५,००० वितरण तथा सङ्कलन सवारी चालक पद</strong> र <strong>२,१०० HGV र MGV सवारी चालक पद</strong> छन्।</p><p>काम अक्टोबर २०२६ अन्त्यदेखि जनवरी २०२७ सुरुसम्म चल्छ — क्रिसमसको चाप, रोयल मेलको वर्षको सबैभन्दा व्यस्त समय। धेरैजसो पद छोटो अवधिका र मौसमी हुन्, स्थायी जागिर होइनन्।</p><h2>कसले आवेदन दिन सक्छ</h2><p>छानबिन र धेरैजसो अन्य पदका लागि अघिल्लो अनुभव आवश्यक छैन। आवेदकले रोयल मेलको भर्ती जाँच पूरा गर्नुपर्छ। सवारी चालक पदका लागि सम्बन्धित अनुमतिपत्र चाहिन्छ — HGV र MGV चालक पदका लागि HGV वा MGV अनुमतिपत्र आवश्यक छ।</p><p>बेलायतमा कानुनी रूपमा काम गर्न पाउने जो कोहीले आवेदन दिन सक्छन्। यी पदहरू अस्थायी क्रिसमस काम खोज्ने विद्यार्थी, अंशकालीन कामदार र डिसेम्बरमा थप आम्दानी चाहनेहरूका लागि उपयुक्त छन्।</p><h2>कसरी आवेदन दिने</h2><ol><li>careers.royalmailgroup.com/christmas मा जानुहोस्।</li><li>आफ्नो क्षेत्र र चाहेको पद छान्नुहोस्।</li><li>अनलाइन आवेदन पूरा गर्नुहोस् र भर्ती जाँच गर्नुहोस्।</li></ol><p>निश्चित अन्तिम मिति नभएकाले र सीमा पुगेपछि पद बन्द हुने भएकाले जति सक्दो चाँडो आवेदन दिनुहोस् — लोकप्रिय स्थानहरू पहिले भरिन्छन्।</p><h2>घोषणामा के छैन</h2><p>रोयल मेलले निश्चित अन्तिम मिति प्रकाशित गरेको छैन र घोषणामा पदहरूको तलब दर उल्लेख छैन। एउटा रात्री छानबिन पदको विज्ञापनमा £१६.४४ प्रति घण्टा भनिएको कुरा अनलाइनमा उद्धृत गरिएको छ, तर त्यो एउटै विज्ञापनबाट आएको हो, आधिकारिक घोषणाबाट होइन — त्यसलाई यी पदहरूको तलब नठान्नुहोस्। तलब र घण्टाका लागि रोयल मेलको करियर साइटमा सम्बन्धित रिक्त पद हेर्नुहोस्।</p><p>रोयल मेलको जागिर दिलाइदिने भन्दै कसैलाई पनि पैसा नदिनुहोस्। आधिकारिक करियर साइटमा आवेदन निःशुल्क छ र कुनै दलालले छनोटमा असर पार्न सक्दैन।</p><h2>स्रोतहरू</h2><p>आधिकारिक क्रिसमस हब: <a href="https://careers.royalmailgroup.com/christmas">careers.royalmailgroup.com/christmas</a>। घोषणा रिपोर्ट: The Mirror, २९ सेप्टेम्बर २०२६; The Sun; Daily Express।</p>$$,
ARRAY['https://careers.royalmailgroup.com/christmas', 'https://www.mirror.co.uk/news/uk-news/royal-mail-christmas-jobs-2026-37982842'], NOW(), NOW(), NOW()) ON CONFLICT ("slug") DO NOTHING;

-- correctional-officer-jobs-canada-24-locations-20261116 (English 493 words; Nepali 291 words)
INSERT INTO "Article" ("id", "slug", "category", "country", "titleEn", "titleNe", "excerptEn", "excerptNe", "bodyEn", "bodyNe", "sources", "publishedAt", "createdAt", "updatedAt")
VALUES
(gen_random_uuid(), 'correctional-officer-jobs-canada-24-locations-20261116', 'canada', 'Canada',
'Correctional Officer Jobs in Canada 2026: Federal Roles Across 24 Locations, Salary up to $97,266',
'क्यानडा सुधार अधिकारी जागिर २०२६: २४ स्थानमा संघीय पद, तलब $९७,२६६ सम्म',
'Correctional Service Canada is hiring Correctional Officer I staff across 24 locations in eight provinces. The pay range is $77,510 to $97,266 a year and applications close on 31 December 2026.',
'क्यानडाको सुधार सेवाले आठ प्रान्तका २४ स्थानमा सुधार अधिकारी I कर्मचारी भर्ती गर्दैछ। तलब वार्षिक $७७,५१० देखि $९७,२६६ छ र आवेदन ३१ डिसेम्बर २०२६ मा बन्द हुन्छ।',
$$<p>Correctional Service Canada is hiring <strong>Correctional Officer I</strong> staff across <strong>24 locations in eight provinces</strong>. The federal roles pay <strong>$77,510 to $97,266 a year</strong>, and applications close on <strong>31 December 2026</strong>.</p><p>The postings cover the Pacific, Prairies, Ontario, Quebec and Atlantic regions. Applications are made through the Government of Canada jobs portal, <a href="https://www.jobs.gc.ca">jobs.gc.ca</a> — search for Correctional Officer I.</p><h2>At a glance</h2><table><tr><th>Detail</th><th>Information</th></tr><tr><td>Role</td><td>Correctional Officer I</td></tr><tr><td>Employer</td><td>Correctional Service Canada</td></tr><tr><td>Locations</td><td>24 locations across 8 provinces</td></tr><tr><td>Pay</td><td>$77,510–$97,266 per year</td></tr><tr><td>Last date</td><td>31 December 2026</td></tr><tr><td>Apply online</td><td>jobs.gc.ca</td></tr><tr><td>Fee</td><td>None</td></tr></table><h2>What it offers</h2><p>Correctional Officers work in federal institutions, supervising offenders, maintaining security and supporting rehabilitation. The role is a federal public service position with a defined salary range and federal benefits.</p><p>The 24 locations span the country, from the Pacific region through the Prairies and Ontario to Quebec and the Atlantic provinces, so candidates in most parts of Canada can find a posting near them.</p><h2>Who can apply</h2><p>Applicants need a high school diploma or equivalent. Selection involves extensive assessments, a medical evaluation and a psychological evaluation, followed by the Correctional Training Program (CTP) for successful candidates.</p><p>Bilingual candidates receive a bonus under the federal hiring process, reflecting the value of English and French in federal institutions.</p><h2>How to apply</h2><ol><li>Go to jobs.gc.ca, the Government of Canada jobs portal.</li><li>Search for Correctional Officer I.</li><li>Choose the location you want and apply online before 31 December 2026.</li></ol><p>Because the process includes multiple assessments and training, apply early — the closing date is 31 December, but the selection process itself takes time.</p><h2>What the posting does not say</h2><p>The sources do not state the exact number of posts, or how many seats are available at each location. The posting is presented as a national intake across 24 locations rather than a fixed vacancy count, so candidates should check the individual location posting on jobs.gc.ca for the details that matter to them.</p><p>Never pay anyone who offers to get you a federal job in Canada. Government of Canada hiring is free, and no agent can influence a selection.</p><h2>Sources</h2><p>Government of Canada jobs portal: <a href="https://www.jobs.gc.ca">jobs.gc.ca</a>. Posting reporting: Immigration News Canada, 12 November 2026; Canada Government Jobs.</p>$$,
$$<p>क्यानडाको सुधार सेवा (Correctional Service Canada) ले <strong>आठ प्रान्तका २४ स्थान</strong> मा <strong>सुधार अधिकारी I</strong> कर्मचारी भर्ती गर्दैछ। संघीय पदको तलब <strong>वार्षिक $७७,५१० देखि $९७,२६६</strong> छ र आवेदन <strong>३१ डिसेम्बर २०२६</strong> मा बन्द हुन्छ।</p><p>पदहरू प्यासिफिक, प्रेरी, ओन्टारियो, क्युबेक र एट्लान्टिक क्षेत्रमा छन्। आवेदन क्यानडा सरकारको जागिर पोर्टल <a href="https://www.jobs.gc.ca">jobs.gc.ca</a> बाट दिन सकिन्छ — Correctional Officer I खोज्नुहोस्।</p><h2>एक नजरमा</h2><table><tr><th>विवरण</th><th>जानकारी</th></tr><tr><td>पद</td><td>सुधार अधिकारी I</td></tr><tr><td>रोजगारदाता</td><td>क्यानडाको सुधार सेवा</td></tr><tr><td>स्थान</td><td>८ प्रान्तमा २४ स्थान</td></tr><tr><td>तलब</td><td>वार्षिक $७७,५१०–$९७,२६६</td></tr><tr><td>अन्तिम मिति</td><td>३१ डिसेम्बर २०२६</td></tr><tr><td>अनलाइन आवेदन</td><td>jobs.gc.ca</td></tr><tr><td>शुल्क</td><td>छैन</td></tr></table><h2>के छ</h2><p>सुधार अधिकारीहरूले संघीय संस्थाहरूमा काम गर्छन् — अपराधीहरूको निगरानी, सुरक्षाको रखरखाव र पुनर्स्थापनामा सहयोग। यो संघीय सार्वजनिक सेवा पद हो, निश्चित तलब दायरा र संघीय सुविधासहित।</p><p>२४ स्थान देशभरि फैलिएका छन् — प्यासिफिक क्षेत्रदेखि प्रेरी र ओन्टारियो हुँदै क्युबेक र एट्लान्टिक प्रान्तसम्म — त्यसैले क्यानडाका धेरै भागका उम्मेदवारले आफू नजिकको पद पाउन सक्छन्।</p><h2>कसले आवेदन दिन सक्छ</h2><p>आवेदकसँग उच्च माध्यमिक डिप्लोमा वा सो सरह हुनुपर्छ। छनोटमा विस्तृत मूल्याङ्कन, चिकित्सा परीक्षण र मनोवैज्ञानिक मूल्याङ्कन हुन्छ, त्यसपछि सफल उम्मेदवारले सुधार प्रशिक्षण कार्यक्रम (CTP) पूरा गर्नुपर्छ।</p><p>द्विभाषी उम्मेदवारलाई संघीय भर्ती प्रक्रियामा बोनस दिइन्छ, किनभने संघीय संस्थाहरूमा अङ्ग्रेजी र फ्रेन्च दुवैको मूल्य छ।</p><h2>कसरी आवेदन दिने</h2><ol><li>क्यानडा सरकारको जागिर पोर्टल jobs.gc.ca मा जानुहोस्।</li><li>Correctional Officer I खोज्नुहोस्।</li><li>चाहेको स्थान छानेर ३१ डिसेम्बर २०२६ अघि अनलाइन आवेदन दिनुहोस्।</li></ol><p>प्रक्रियामा धेरै मूल्याङ्कन र प्रशिक्षण पर्ने भएकाले चाँडै आवेदन दिनुहोस् — अन्तिम मिति ३१ डिसेम्बर हो, तर छनोट प्रक्रिया आफैंमा समय लिन्छ।</p><h2>विज्ञापनमा के छैन</h2><p>स्रोतहरूमा पदहरूको ठ्याक्कै संख्या वा प्रत्येक स्थानमा कति सिट छन् भन्ने उल्लेख छैन। यो विज्ञापन निश्चित रिक्त संख्याभन्दा २४ स्थानमा राष्ट्रिय भर्नाका रूपमा प्रस्तुत गरिएको छ, त्यसैले उम्मेदवारले आफूलाई महत्त्वपूर्ण विवरण jobs.gc.ca मा सम्बन्धित स्थानको विज्ञापनमा हेर्नुपर्छ।</p><p>क्यानडामा संघीय जागिर दिलाइदिने भन्दै कसैलाई पनि पैसा नदिनुहोस्। क्यानडा सरकारको भर्ती निःशुल्क छ र कुनै दलालले छनोटमा असर पार्न सक्दैन।</p><h2>स्रोतहरू</h2><p>क्यानडा सरकारको जागिर पोर्टल: <a href="https://www.jobs.gc.ca">jobs.gc.ca</a>। विज्ञापन रिपोर्ट: Immigration News Canada, १२ नोभेम्बर २०२६; Canada Government Jobs।</p>$$,
ARRAY['https://www.jobs.gc.ca', 'https://immigrationnewscanada.ca/correctional-officer-jobs-in-canada-2026'], NOW(), NOW(), NOW()) ON CONFLICT ("slug") DO NOTHING;

-- oaic-investigator-jobs-australia-aps5-aps6-20261116 (English 532 words; Nepali 308 words)
INSERT INTO "Article" ("id", "slug", "category", "country", "titleEn", "titleNe", "excerptEn", "excerptNe", "bodyEn", "bodyNe", "sources", "publishedAt", "createdAt", "updatedAt")
VALUES
(gen_random_uuid(), 'oaic-investigator-jobs-australia-aps5-aps6-20261116', 'australia', 'Australia',
'OAIC Investigator Jobs Australia 2026: APS5 and APS6 Roles, Salary up to $111,702',
'OAIC अनुसन्धानकर्ता जागिर अस्ट्रेलिया २०२६: APS5 र APS6 पद, तलब $१११,७०२ सम्म',
'The Office of the Australian Information Commissioner is hiring APS5 Investigators and APS6 Senior Investigators. Applications close at 11:59 PM AEDT on Monday 23 November 2026.',
'अस्ट्रेलियन सूचना आयुक्तको कार्यालयले APS5 अनुसन्धानकर्ता र APS6 वरिष्ठ अनुसन्धानकर्ता भर्ती गर्दैछ। आवेदन सोमबार २३ नोभेम्बर २०२६ राति ११:५९ बजे AEDT मा बन्द हुन्छ।',
$$<p>The Office of the Australian Information Commissioner (OAIC) is hiring <strong>APS5 Investigators and APS6 Senior Investigators</strong>, along with an APS6 Senior Compliance Officer. The roles are advertised under reference OAIC-2026-021, and applications close at <strong>11:59 PM AEDT on Monday 23 November 2026</strong>.</p><p>Applications are made by email to <a href="mailto:jobs@oaic.gov.au">jobs@oaic.gov.au</a> — an application form, a CV of no more than three pages, and a one-page pitch. The full job pack is on the OAIC website.</p><h2>At a glance</h2><table><tr><th>Detail</th><th>Information</th></tr><tr><td>Roles</td><td>APS5 Investigator; APS6 Senior Investigator; APS6 Senior Compliance Officer</td></tr><tr><td>Reference</td><td>OAIC-2026-021</td></tr><tr><td>Employer</td><td>Office of the Australian Information Commissioner</td></tr><tr><td>Last date</td><td>11:59 PM AEDT, Monday 23 November 2026</td></tr><tr><td>Apply by email</td><td>jobs@oaic.gov.au</td></tr><tr><td>Fee</td><td>None</td></tr></table><h2>What it offers</h2><p>OAIC investigators handle complaints and investigations under Australian privacy and freedom of information law. The APS5 roles suit investigators with one to three years of relevant experience, while the APS6 roles need three to five or more years.</p><p>The pay is <strong>APS5 $90,883–$96,829</strong> and <strong>APS6 $100,215–$111,702</strong>, plus 15.4% superannuation. The roles are based in the Sydney CBD, with hybrid working, and other Australian locations are considered.</p><h2>Who can apply</h2><p>Applicants must be <strong>Australian citizens</strong> under the Public Service Act, and must be able to hold a Baseline security clearance. The OAIC is looking for backgrounds in investigations, regulation, legal and policy work. A Certificate IV in Government Investigations is highly desirable.</p><h2>How to apply</h2><ol><li>Download the job pack from the OAIC vacancies page.</li><li>Prepare the application form, a CV of no more than three pages and a one-page pitch addressing the role.</li><li>Email the application to jobs@oaic.gov.au by 11:59 PM AEDT on Monday 23 November 2026.</li></ol><p>The closing time is 11:59 PM AEDT — check the time zone if you are applying from another Australian state.</p><h2>What the vacancy does not say</h2><p>The vacancy page does not state the exact number of roles available. It lists the three role types and the reference number, but not a headcount, so candidates should treat it as a multi-role intake rather than a fixed number of posts.</p><p>Never pay anyone who offers to get you an Australian public service job. Applications to the OAIC are free, and no agent can influence a selection.</p><h2>Sources</h2><p>Official vacancy page: <a href="https://www.oaic.gov.au/about-the-OAIC/join-our-team/vacancies/aps5-investigators_aps6-senior-investigators">oaic.gov.au — APS5 Investigators and APS6 Senior Investigators</a> (published 9 November 2026, reference OAIC-2026-021).</p>$$,
$$<p>अस्ट्रेलियन सूचना आयुक्तको कार्यालय (OAIC) ले <strong>APS5 अनुसन्धानकर्ता र APS6 वरिष्ठ अनुसन्धानकर्ता</strong> पदहरू, साथै APS6 वरिष्ठ अनुपालन अधिकारी पदका लागि भर्ती गर्दैछ। यी पदहरू सन्दर्भ OAIC-2026-021 अन्तर्गत विज्ञापित छन् र आवेदन <strong>सोमबार २३ नोभेम्बर २०२६ राति ११:५९ बजे AEDT</strong> मा बन्द हुन्छ।</p><p>आवेदन इमेलबाट <a href="mailto:jobs@oaic.gov.au">jobs@oaic.gov.au</a> मा दिन सकिन्छ — आवेदन फारम, तीन पृष्ठभन्दा बढी नहुने CV र एक पृष्ठको पिच। पूरा जागिर प्याक OAIC वेबसाइटमा छ।</p><h2>एक नजरमा</h2><table><tr><th>विवरण</th><th>जानकारी</th></tr><tr><td>पद</td><td>APS5 अनुसन्धानकर्ता; APS6 वरिष्ठ अनुसन्धानकर्ता; APS6 वरिष्ठ अनुपालन अधिकारी</td></tr><tr><td>सन्दर्भ</td><td>OAIC-2026-021</td></tr><tr><td>रोजगारदाता</td><td>अस्ट्रेलियन सूचना आयुक्तको कार्यालय</td></tr><tr><td>अन्तिम मिति</td><td>राति ११:५९ बजे AEDT, सोमबार २३ नोभेम्बर २०२६</td></tr><tr><td>इमेलबाट आवेदन</td><td>jobs@oaic.gov.au</td></tr><tr><td>शुल्क</td><td>छैन</td></tr></table><h2>के छ</h2><p>OAIC अनुसन्धानकर्ताहरूले अस्ट्रेलियाको गोपनीयता र सूचनाको स्वतन्त्रता कानुनअन्तर्गत उजुरी र अनुसन्धान सम्हाल्छन्। APS5 पदहरू एकदेखि तीन वर्षको सम्बन्धित अनुभव भएकाहरूका लागि उपयुक्त छन् भने APS6 पदहरूमा तीनदेखि पाँच वर्ष वा बढी अनुभव चाहिन्छ।</p><p>तलब <strong>APS5 $९०,८८३–$९६,८२९</strong> र <strong>APS6 $१००,२१५–$१११,७०२</strong> छ, साथमा १५.४% सुपरएन्युएसन। पदहरू सिड्नी CBD मा आधारित छन्, हाइब्रिड कार्यसहित, र अस्ट्रेलियाका अन्य स्थानहरू पनि विचार गरिन्छ।</p><h2>कसले आवेदन दिन सक्छ</h2><p>आवेदक सार्वजनिक सेवा ऐनअन्तर्गत <strong>अस्ट्रेलियाली नागरिक</strong> हुनुपर्छ र बेसलाइन सुरक्षा स्वीकृति लिन सक्नुपर्छ। OAIC ले अनुसन्धान, नियमन, कानुनी र नीतिगत पृष्ठभूमि भएकाहरूलाई खोजिरहेको छ। सरकारी अनुसन्धानमा प्रमाणपत्र IV अत्यधिक वाञ्छनीय छ।</p><h2>कसरी आवेदन दिने</h2><ol><li>OAIC रिक्त पद पृष्ठबाट जागिर प्याक डाउनलोड गर्नुहोस्।</li><li>आवेदन फारम, तीन पृष्ठभन्दा बढी नहुने CV र पदबारे एक पृष्ठको पिच तयार गर्नुहोस्।</li><li>सोमबार २३ नोभेम्बर २०२६ राति ११:५९ बजे AEDT सम्म jobs@oaic.gov.au मा आवेदन इमेल गर्नुहोस्।</li></ol><p>बन्द हुने समय राति ११:५९ बजे AEDT हो — अर्को अस्ट्रेलियाली राज्यबाट आवेदन दिँदै हुनुहुन्छ भने समय क्षेत्र हेर्नुहोस्।</p><h2>रिक्त पदमा के छैन</h2><p>रिक्त पदको पृष्ठमा पदहरूको ठ्याक्कै संख्या उल्लेख छैन। यसमा तीन प्रकारका पद र सन्दर्भ नम्बर सूचीबद्ध छन्, तर संख्या छैन, त्यसैले उम्मेदवारले यसलाई निश्चित संख्याको पदभन्दा धेरै पदको भर्नाका रूपमा बुझ्नुपर्छ।</p><p>अस्ट्रेलियाली सार्वजनिक सेवा जागिर दिलाइदिने भन्दै कसैलाई पनि पैसा नदिनुहोस्। OAIC मा आवेदन निःशुल्क छ र कुनै दलालले छनोटमा असर पार्न सक्दैन।</p><h2>स्रोतहरू</h2><p>आधिकारिक रिक्त पद पृष्ठ: <a href="https://www.oaic.gov.au/about-the-OAIC/join-our-team/vacancies/aps5-investigators_aps6-senior-investigators">oaic.gov.au — APS5 अनुसन्धानकर्ता र APS6 वरिष्ठ अनुसन्धानकर्ता</a> (९ नोभेम्बर २०२६ मा प्रकाशित, सन्दर्भ OAIC-2026-021)।</p>$$,
